		OnStart: func(ctx context.Context) error {
			go func() {
				// Detach cancellation from the hook context since UberFx cancels it
				// after OnStart returns, which would stop the river client listeners.
				detachedCtx := context.WithoutCancel(ctx)
				if err := client.Start(detachedCtx); err != nil {
					logger.Error(detachedCtx, "error starting river client", err)
					shutdown(detachedCtx, shutdowner, logger)
				}
			}()
			return nil
		},
		OnStop: func(ctx context.Context) error {
			// This stop will finish current running jobs before shutting down.
			// If there is a policy which has a long sync time, the shutdown might
			// take a while.
			return client.Stop(ctx)
		},
	}

